def handle(msg):
    if isinstance(msg, list):
        out = [r for r in (handle(m) for m in msg) if r is not None]
        return out or None
    if not isinstance(msg, dict) or msg.get("jsonrpc") != "2.0":
        return _err(msg.get("id") if isinstance(msg, dict) else None, -32600, "Invalid Request")
    method, mid, params = msg.get("method"), msg.get("id"), msg.get("params") or {}
    if method is None:  # đây là response từ client, bỏ qua
        return None
    if mid is None:  # notification
        return None
    if method == "initialize":
        want = params.get("protocolVersion")
        return _ok(mid, {"protocolVersion": want if want in SUPPORTED else SUPPORTED[0],
                         "capabilities": {"tools": {"listChanged": False}, "resources": {"listChanged": False},
                                          "prompts": {"listChanged": False}},
                         "serverInfo": {"name": "officeai", "version": VERSION},
                         "instructions": INSTRUCTIONS})
    if method == "ping":
        return _ok(mid, {})
    if method == "tools/list":
        return _ok(mid, {"tools": [{k: v for k, v in t.items() if k != "_impl"} for t in TOOLS]})
    if method == "tools/call":
        name, args = params.get("name"), params.get("arguments") or {}
        if name not in TOOL_MAP:
            return _err(mid, -32602, f"Unknown tool: {name}")
        if not isinstance(args, dict):
            return _err(mid, -32602, "arguments must be an object")
        return _ok(mid, call_tool(name, args))
    if method == "resources/list":
        return _ok(mid, {"resources": RESOURCES})
    if method == "resources/read":
        uri = params.get("uri")
        if isinstance(uri, str) and "://skill/" in uri:
            key = uri.rsplit("://skill/", 1)[1]
